-- Clip D8.6: the identity columns of the source, written as PostgreSQL statements.
-- SQL Server 2022 (sql2022), sqlcmd -h -1, database PachaDataFormation, read only.
-- 06-cutover.sh sends the output to psql, on the tables that pgloader created without them.
SET NOCOUNT ON;
SELECT CONCAT('alter table ', LOWER(SCHEMA_NAME(t.schema_id)), '.', LOWER(t.name),
              ' alter column ', LOWER(ic.name), ' add generated by default as identity;')
FROM sys.identity_columns AS ic
JOIN sys.tables AS t ON t.object_id = ic.object_id
WHERE SCHEMA_NAME(t.schema_id) IN ('Stage', 'Inscription', 'Formateur', 'Contact', 'Reference')
  AND t.name NOT IN ('ville', 'Region')
ORDER BY 1;
